// Package sprites provides access to the different sprites generated by
// the application (i.e: stars, planets)
package sprites

// Sprite holds the name and base64-encoded PNG data for a single sprite.
type Sprite struct {
	Name     string
	B64Value string
}

type Size uint8

const (
	Small Size = iota
	Medium
	Large
	Special
)

